// JAH demo program — Rung builder
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function rungs(){return ['count','add','multiply','fractions','negatives','algebra','functions','limits','derivatives','integrals'];}
var r=rungs();
check("10 rungs", r.length, 10);
check("calculus needs algebra (rung 6 before 9)", r.indexOf('algebra')<r.indexOf('derivatives'), true);
check("starts with counting", r[0], "count");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

